mapper.select:
select * from a2a_policies
where tenant_id=#{tenantId}
and upper(source_domain_id)=upper(#{sourceDomainId})
and upper(target_domain_id)=upper(#{targetDomainId})
order by policy_code limit #{limit}

select p.* from a2a_policies p
where p.tenant_id=#{tenantId}
and upper(p.source_domain_id)=upper(#{sourceDomainId})
and upper(p.target_domain_id)=upper(#{targetDomainId})

 and 1=0

  and (
    1=0

     or p.source_department_id in #{id}
     or p.target_department_id in #{id}


     or exists (select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.source_department_id and dc.ancestor_department_id in #{id})
     or exists (select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.target_department_id and dc.ancestor_department_id in #{id})


     or p.source_group_id in #{id}
     or p.target_group_id in #{id}


     or p.policy_id in #{id}

  )



 and p.policy_id not in #{id}


 and (p.source_department_id is null or p.source_department_id not in #{id})
 and (p.target_department_id is null or p.target_department_id not in #{id})


 and not exists (select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.source_department_id and dc.ancestor_department_id in #{id})
 and not exists (select 1 from org_department_closure dc where dc.tenant_id=p.tenant_id and dc.descendant_department_id=p.target_department_id and dc.ancestor_department_id in #{id})


 and (p.source_group_id is null or p.source_group_id not in #{id})
 and (p.target_group_id is null or p.target_group_id not in #{id})

order by p.policy_code limit #{limit}
